'use strict';

const fs = require('fs');
const path = require('path');

const ELF_PATH = process.argv[2] || '/app/doomgeneric_mips';
const WAD_PATH = process.argv[3] || '/app/doom.wad';

// ----- ELF loader (MIPS32 little-endian) -----

function loadELF(filePath) {
    const data = fs.readFileSync(filePath);
    // Verify magic
    if (data[0] !== 0x7f || data[1] !== 0x45 || data[2] !== 0x4c || data[3] !== 0x46) {
        throw new Error('Not an ELF file');
    }
    if (data[4] !== 1) throw new Error('Not 32-bit ELF');
    if (data[5] !== 1) throw new Error('Not little-endian ELF');
    const e_machine = data.readUInt16LE(18);
    if (e_machine !== 8) throw new Error('Not MIPS ELF');

    const e_entry = data.readUInt32LE(24);
    const e_phoff = data.readUInt32LE(28);
    const e_phentsize = data.readUInt16LE(42);
    const e_phnum = data.readUInt16LE(44);

    const segments = [];
    for (let i = 0; i < e_phnum; i++) {
        const off = e_phoff + i * e_phentsize;
        const p_type = data.readUInt32LE(off);
        if (p_type !== 1) continue; // PT_LOAD only
        const p_offset = data.readUInt32LE(off + 4);
        const p_vaddr = data.readUInt32LE(off + 8);
        const p_filesz = data.readUInt32LE(off + 16);
        const p_memsz = data.readUInt32LE(off + 20);
        const p_flags = data.readUInt32LE(off + 24);
        segments.push({ p_offset, p_vaddr, p_filesz, p_memsz, p_flags });
    }

    // Determine memory range: from min vaddr to max(vaddr+memsz), and add stack at top
    let minAddr = 0xffffffff;
    let maxAddr = 0;
    for (const s of segments) {
        if (s.p_vaddr < minAddr) minAddr = s.p_vaddr;
        const end = s.p_vaddr + s.p_memsz;
        if (end > maxAddr) maxAddr = end;
    }

    // Pad up to a page boundary, then add stack space
    const pageSize = 0x10000;
    const alignedMax = (Math.floor(maxAddr / pageSize) + 1) * pageSize;

    // Place stack near top of 32-bit address space (under 0x80000000)
    // Use 16 MB of stack space
    const STACK_SIZE = 16 * 1024 * 1024;
    const STACK_TOP = 0x7fff0000;
    const STACK_BOTTOM = STACK_TOP - STACK_SIZE;

    const memSize = Math.max(alignedMax, STACK_TOP) - minAddr;
    const memBase = minAddr;
    const memory = new Uint8Array(memSize);
    const memI32 = new Int32Array(memory.buffer);
    const memU32 = new Uint32Array(memory.buffer);

    // Load segments
    for (const s of segments) {
        const dst = s.p_vaddr - memBase;
        if (s.p_filesz > 0) {
            const chunk = data.subarray(s.p_offset, s.p_offset + s.p_filesz);
            memory.set(chunk, dst);
        }
        // Zero BSS already done by Uint8Array initialization
    }

    return {
        memory,
        memI32,
        memU32,
        memBase,
        memSize,
        entry: e_entry,
        segments,
        stackTop: STACK_TOP,
    };
}

// ----- Memory helpers -----

function memRead32(memU32, addr) {
    const off = addr - this_memBase;
    return memU32[off >>> 2];
}
function memWrite32(memU32, addr, val) {
    const off = addr - this_memBase;
    memU32[off >>> 2] = val >>> 0;
}
function memRead16(memory, addr) {
    const off = addr - this_memBase;
    return memory[off] | (memory[off + 1] << 8);
}
function memWrite16(memory, addr, val) {
    const off = addr - this_memBase;
    memory[off] = val & 0xff;
    memory[off + 1] = (val >> 8) & 0xff;
}
function memRead8(memory, addr) {
    return memory[addr - this_memBase];
}
function memWrite8(memory, addr, val) {
    memory[addr - this_memBase] = val & 0xff;
}

// ----- VM -----

class VM {
    constructor(elf, wadPath) {
        this.elf = elf;
        this.wadPath = wadPath;
        this.memory = elf.memory;
        this.memI32 = elf.memI32;
        this.memU32 = elf.memU32;
        this.memBase = elf.memBase;

        // 32 general-purpose registers, plus HI/LO for mult/div
        this.gpr = new Int32Array(32);
        // 32 single-precision FP registers (or 16 doubles)
        // We'll use a Float32Array view for single precision and Float64Array view for double.
        // We need 32 single registers or 16 double registers.
        // To avoid aliasing issues, store as Uint32 for FPR pairs, and provide accessors.
        // Actually it's simpler: store FP regs as two Uint32 per "logical" 64-bit slot.
        this.fpr_u32 = new Uint32Array(32); // 32 single precision (low 32 bits each)
        this.fpr2_u32 = new Uint32Array(32); // upper 32 bits for paired-single or double high
        // FPU condition codes (8 bits)
        this.fcc = 0;
        // Program counter
        this.pc = elf.entry >>> 0;
        this.nextPc = (this.pc + 4) >>> 0;
        // HI/LO
        this.hi = 0;
        this.lo = 0;
        // File descriptors
        this.fds = {}; // map of integer fd -> {path, realFd, mode}
        this.nextFd = 3;
        // File table to map MIPS fd -> host fd
        this.fdTable = {};
        this.stdoutBuf = [];
        this.stderrBuf = [];
        // Time
        this.startMs = Date.now();
        // Stall flag (for debugging)
        this.exited = false;
        this.exitCode = 0;
        this.icount = 0;
        // Frame counter
        this.frameCount = 0;
    }

    // Memory accessors using this
    memOffset(addr) {
        return (addr - this.memBase) >>> 0;
    }

    read32(addr) {
        const off = this.memOffset(addr);
        return this.memU32[off >>> 2];
    }
    write32(addr, val) {
        const off = this.memOffset(addr);
        this.memU32[off >>> 2] = val >>> 0;
    }
    read16(addr) {
        const off = this.memOffset(addr);
        return this.memory[off] | (this.memory[off + 1] << 8);
    }
    write16(addr, val) {
        const off = this.memOffset(addr);
        this.memory[off] = val & 0xff;
        this.memory[off + 1] = (val >> 8) & 0xff;
    }
    read8(addr) {
        return this.memory[this.memOffset(addr)];
    }
    write8(addr, val) {
        this.memory[this.memOffset(addr)] = val & 0xff;
    }
    // Read C-string (null-terminated) from memory
    readCString(addr, maxLen = 4096) {
        const off = this.memOffset(addr);
        let end = off;
        const limit = Math.min(off + maxLen, this.memory.length);
        while (end < limit && this.memory[end] !== 0) end++;
        return this.memory.slice(off, end).toString('utf8');
    }
    readBytes(addr, len) {
        const off = this.memOffset(addr);
        return this.memory.slice(off, off + len);
    }
    writeBytes(addr, buf) {
        const off = this.memOffset(addr);
        this.memory.set(buf, off);
    }

    setReg(i, val) {
        if (i !== 0) this.gpr[i] = val | 0;
    }
    getReg(i) {
        return this.gpr[i] | 0;
    }
    getRegU(i) {
        return this.gpr[i] >>> 0;
    }
    setFprSingle(i, val) {
        // Single precision: store bits in fpr_u32[i]
        const buf = new ArrayBuffer(4);
        const f32 = new Float32Array(buf);
        const u32 = new Uint32Array(buf);
        f32[0] = val;
        this.fpr_u32[i] = u32[0];
        this.fpr2_u32[i] = 0; // upper half for double (clear)
    }
    getFprSingle(i) {
        const buf = new ArrayBuffer(4);
        const f32 = new Float32Array(buf);
        const u32 = new Uint32Array(buf);
        u32[0] = this.fpr_u32[i];
        return f32[0];
    }
    setFprDouble(i, val) {
        // Double precision: store bits in fpr_u32[i] (low) and fpr2_u32[i] (high)
        const buf = new ArrayBuffer(8);
        const f64 = new Float64Array(buf);
        const u32 = new Uint32Array(buf);
        f64[0] = val;
        this.fpr_u32[i] = u32[0];
        this.fpr2_u32[i] = u32[1];
    }
    getFprDouble(i) {
        const buf = new ArrayBuffer(8);
        const f64 = new Float64Array(buf);
        const u32 = new Uint32Array(buf);
        u32[0] = this.fpr_u32[i];
        u32[1] = this.fpr2_u32[i];
        return f64[0];
    }
    setFprWord(i, val) {
        this.fpr_u32[i] = val >>> 0;
        this.fpr2_u32[i] = 0;
    }
    getFprWord(i) {
        // Interpret low 32 bits as signed int (signed)
        return this.fpr_u32[i] | 0;
    }
    setFprLong(i, lo, hi) {
        this.fpr_u32[i] = lo >>> 0;
        this.fpr2_u32[i] = hi >>> 0;
    }

    getFcc(cc) {
        return (this.fcc >>> cc) & 1;
    }
    setFcc(cc, val) {
        if (val) this.fcc |= (1 << cc);
        else this.fcc &= ~(1 << cc);
    }

    // ----- Syscall handler -----

    // Map MIPS syscall numbers (which are x86_64-style in this binary) to handlers.
    // SYS_read = 0, SYS_write = 1, SYS_open = 2, SYS_close = 3
    // SYS_lseek = 8, SYS_mmap = 9, SYS_brk = 12
    // SYS_nanosleep = 35, SYS_exit = 60, SYS_fsync = 74
    // SYS_rename = 82, SYS_mkdir = 83, SYS_unlink = 87
    // SYS_gettimeofday = 96, SYS_time = 201
    syscall() {
        const num = this.getRegU(2); // $v0
        const a0 = this.getRegU(4); // $a0
        const a1 = this.getRegU(5); // $a1
        const a2 = this.getRegU(6); // $a2
        const a3 = this.getRegU(7); // $a3
        let result = 0;
        switch (num) {
            case 0: { // SYS_read
                const fd = a0;
                const buf = a1;
                const count = a2;
                if (this.fdTable[fd] === undefined) {
                    result = -9; // EBADF
                    break;
                }
                try {
                    const tmp = Buffer.alloc(count);
                    const n = fs.readSync(this.fdTable[fd], tmp, 0, count, null);
                    if (n > 0) this.writeBytes(buf, tmp.subarray(0, n));
                    result = n;
                } catch (e) {
                    result = -5; // EIO
                }
                break;
            }
            case 1: { // SYS_write
                const fd = a0;
                const buf = a1;
                const count = a2;
                if (fd === 1) {
                    // stdout
                    const data = this.readBytes(buf, count);
                    const str = data.toString('utf8');
                    process.stdout.write(str);
                    result = count;
                } else if (fd === 2) {
                    // stderr
                    const data = this.readBytes(buf, count);
                    const str = data.toString('utf8');
                    process.stderr.write(str);
                    result = count;
                } else if (this.fdTable[fd] !== undefined) {
                    const data = this.readBytes(buf, count);
                    try {
                        fs.writeSync(this.fdTable[fd], data, 0, count, null);
                        result = count;
                    } catch (e) {
                        result = -5;
                    }
                } else {
                    result = -9;
                }
                break;
            }
            case 2: { // SYS_open
                const pathname = this.readCString(a0);
                const flags = a1;
                const mode = a2;
                const O_RDONLY = 0;
                const O_WRONLY = 1;
                const O_RDWR = 2;
                const O_CREAT = 64;
                const O_EXCL = 128;
                const O_TRUNC = 512;
                const O_APPEND = 1024;
                let openFlags = 0;
                const access = flags & 3;
                if (access === O_RDONLY) openFlags |= fs.constants.O_RDONLY;
                else if (access === O_WRONLY) openFlags |= fs.constants.O_WRONLY;
                else if (access === O_RDWR) openFlags |= fs.constants.O_RDWR;
                if (flags & O_CREAT) openFlags |= fs.constants.O_CREAT;
                if (flags & O_EXCL) openFlags |= fs.constants.O_EXCL;
                if (flags & O_TRUNC) openFlags |= fs.constants.O_TRUNC;
                if (flags & O_APPEND) openFlags |= fs.constants.O_APPEND;
                try {
                    const realFd = fs.openSync(pathname, openFlags, mode || 0o644);
                    const mipsFd = this.nextFd++;
                    this.fdTable[mipsFd] = realFd;
                    result = mipsFd;
                } catch (e) {
                    if (e.code === 'ENOENT') result = -2;
                    else if (e.code === 'EACCES') result = -13;
                    else if (e.code === 'EEXIST') result = -17;
                    else result = -22;
                }
                break;
            }
            case 3: { // SYS_close
                const fd = a0;
                if (this.fdTable[fd] !== undefined) {
                    try {
                        fs.closeSync(this.fdTable[fd]);
                    } catch (e) {}
                    delete this.fdTable[fd];
                    result = 0;
                } else {
                    result = -9;
                }
                break;
            }
            case 8: { // SYS_lseek
                const fd = a0;
                const offset = a1 | 0;
                const whence = a2;
                if (this.fdTable[fd] === undefined) {
                    result = -9;
                    break;
                }
                // Get current position
                let curPos = 0;
                try {
                    curPos = fs.fstatSync(this.fdTable[fd]).size; // dummy
                } catch (e) {}
                // We need real position tracking
                if (!this.fdPos) this.fdPos = {};
                let basePos = this.fdPos[fd] || 0;
                let newPos;
                if (whence === 0) newPos = offset;
                else if (whence === 1) newPos = basePos + offset;
                else if (whence === 2) {
                    try {
                        const sz = fs.fstatSync(this.fdTable[fd]).size;
                        newPos = sz + offset;
                    } catch (e) {
                        result = -9;
                        break;
                    }
                } else { result = -22; break; }
                if (newPos < 0) { result = -22; break; }
                this.fdPos[fd] = newPos;
                result = newPos;
                break;
            }
            case 35: { // SYS_nanosleep
                // arg1 = pointer to timespec (sec, nsec)
                const ptr = a0;
                const sec = this.read32(ptr);
                const nsec = this.read32(ptr + 4);
                const ms = sec * 1000 + Math.floor(nsec / 1000000);
                const target = Date.now() + ms;
                while (Date.now() < target) {
                    // Busy wait; not great but simple
                }
                result = 0;
                break;
            }
            case 60: { // SYS_exit
                this.exited = true;
                this.exitCode = a0;
                result = 0;
                break;
            }
            case 74: { // SYS_fsync
                const fd = a0;
                if (this.fdTable[fd] !== undefined) {
                    try {
                        fs.fsyncSync(this.fdTable[fd]);
                    } catch (e) {}
                    result = 0;
                } else {
                    result = -9;
                }
                break;
            }
            case 82: { // SYS_rename
                const oldpath = this.readCString(a0);
                const newpath = this.readCString(a1);
                try {
                    fs.renameSync(oldpath, newpath);
                    result = 0;
                } catch (e) {
                    result = -22;
                }
                break;
            }
            case 83: { // SYS_mkdir
                const pathname = this.readCString(a0);
                const mode = a1;
                try {
                    fs.mkdirSync(pathname, { mode: mode || 0o755, recursive: false });
                    result = 0;
                } catch (e) {
                    if (e.code === 'EEXIST') result = -17;
                    else result = -22;
                }
                break;
            }
            case 87: { // SYS_unlink
                const pathname = this.readCString(a0);
                try {
                    fs.unlinkSync(pathname);
                    result = 0;
                } catch (e) {
                    if (e.code === 'ENOENT') result = -2;
                    else result = -22;
                }
                break;
            }
            case 96: { // SYS_gettimeofday
                const tv = a0;
                if (tv !== 0) {
                    const now = Date.now();
                    const sec = Math.floor(now / 1000);
                    const usec = (now % 1000) * 1000;
                    this.write32(tv, sec);
                    this.write32(tv + 4, usec);
                }
                result = 0;
                break;
            }
            case 201: { // SYS_time
                const tloc = a0;
                const sec = Math.floor(Date.now() / 1000);
                if (tloc !== 0) this.write32(tloc, sec);
                result = sec;
                break;
            }
            default:
                console.error(`[vm] Unimplemented syscall ${num} at pc=0x${(this.pc - 4).toString(16)}`);
                result = -38; // ENOSYS
                break;
        }
        this.setReg(2, result | 0); // $v0
        // Set $a3 = 0 for success, 1 for error (MIPS o32 ABI)
        if (result < 0) {
            // Write errno
            // The binary expects errno to be at 0x4B0A80
            // Let's find this address
            this.write32(0x4b0a80, -result);
            this.setReg(7, 1);
        } else {
            this.setReg(7, 0);
        }
    }

    // ----- Interpreter -----

    step() {
        const pc = this.pc;
        const nextPc = this.nextPc;
        const instr = this.read32(pc);
        this.icount++;

        const op = (instr >>> 26) & 0x3f;
        const rs = (instr >>> 21) & 0x1f;
        const rt = (instr >>> 16) & 0x1f;
        const rd = (instr >>> 11) & 0x1f;
        const sa = (instr >>> 6) & 0x1f;
        const fn = instr & 0x3f;
        const imm = instr & 0xffff;
        const simm = (imm & 0x8000) ? (imm | 0xffff0000) : imm;

        // Default: advance PC and nextPc
        const newPc = nextPc;
        let newNextPc = nextPc + 4;

        switch (op) {
            case 0x00: { // SPECIAL
                switch (fn) {
                    case 0x00: { // SLL
                        if (rd) this.setReg(rd, this.getReg(rt) << sa);
                        break;
                    }
                    case 0x02: { // SRL or ROTR (MIPS32R2: ROTR if rs[0]=1)
                        if ((rs & 1) === 1) {
                            // ROTR
                            const v = this.getRegU(rt);
                            if (rd) this.setReg(rd, ((v >>> sa) | (v << (32 - sa))) | 0);
                        } else {
                            // SRL
                            if (rd) this.setReg(rd, this.getRegU(rt) >>> sa);
                        }
                        break;
                    }
                    case 0x03: { // SRA
                        if (rd) this.setReg(rd, this.getReg(rt) >> sa);
                        break;
                    }
                    case 0x04: { // SLLV
                        if (rd) this.setReg(rd, this.getReg(rt) << (this.getReg(rs) & 0x1f));
                        break;
                    }
                    case 0x06: { // SRLV or ROTRV (MIPS32R2)
                        if ((sa & 1) === 1) {
                            const v = this.getRegU(rt);
                            const s = this.getReg(rs) & 0x1f;
                            if (rd) this.setReg(rd, ((v >>> s) | (v << (32 - s))) | 0);
                        } else {
                            if (rd) this.setReg(rd, this.getRegU(rt) >>> (this.getReg(rs) & 0x1f));
                        }
                        break;
                    }
                    case 0x07: { // SRAV
                        if (rd) this.setReg(rd, this.getReg(rt) >> (this.getReg(rs) & 0x1f));
                        break;
                    }
                    case 0x08: { // JR
                        newNextPc = this.getRegU(rs);
                        break;
                    }
                    case 0x09: { // JALR
                        const target = this.getRegU(rs);
                        if (rd) this.setReg(rd, pc + 8);
                        newNextPc = target;
                        break;
                    }
                    case 0x0a: { // MOVZ
                        if (rt === 0) {
                            if (rd) this.setReg(rd, this.getReg(rs));
                        }
                        break;
                    }
                    case 0x0b: { // MOVN
                        if (rt !== 0) {
                            if (rd) this.setReg(rd, this.getReg(rs));
                        }
                        break;
                    }
                    case 0x0c: { // SYSCALL
                        this.syscall();
                        if (this.exited) {
                            // Force exit
                            return false;
                        }
                        break;
                    }
                    case 0x0d: { // BREAK
                        throw new Error(`BREAK at 0x${pc.toString(16)}`);
                    }
                    case 0x0f: { // SYNC
                        break;
                    }
                    case 0x10: { // MFHI
                        if (rd) this.setReg(rd, this.hi);
                        break;
                    }
                    case 0x11: { // MTHI
                        this.hi = this.getReg(rs);
                        break;
                    }
                    case 0x12: { // MFLO
                        if (rd) this.setReg(rd, this.lo);
                        break;
                    }
                    case 0x13: { // MTLO
                        this.lo = this.getReg(rs);
                        break;
                    }
                    case 0x18: { // MULT
                        {
                            const a = BigInt(this.getReg(rs));
                            const b = BigInt(this.getReg(rt));
                            const prod = a * b;
                            this.lo = Number(BigInt.asIntN(32, prod));
                            this.hi = Number(BigInt.asIntN(32, prod >> 32n));
                        }
                        break;
                    }
                    case 0x19: { // MULTU
                        {
                            const a = BigInt(this.getRegU(rs));
                            const b = BigInt(this.getRegU(rt));
                            const prod = a * b;
                            this.lo = Number(BigInt.asIntN(32, prod));
                            this.hi = Number(BigInt.asIntN(32, prod >> 32n));
                        }
                        break;
                    }
                    case 0x1a: { // DIV
                        {
                            const a = this.getReg(rs);
                            const b = this.getReg(rt);
                            if (b === 0) { this.lo = 0; this.hi = 0; }
                            else if (a === -2147483648 && b === -1) { this.lo = -2147483648; this.hi = 0; }
                            else { this.lo = (a / b) | 0; this.hi = (a % b) | 0; }
                        }
                        break;
                    }
                    case 0x1b: { // DIVU
                        {
                            const a = this.getRegU(rs);
                            const b = this.getRegU(rt);
                            if (b === 0) { this.lo = 0; this.hi = 0; }
                            else { this.lo = (a / b) | 0; this.hi = (a % b) | 0; }
                        }
                        break;
                    }
                    case 0x20: { // ADD (treat as ADDU for our purposes since we don't trap on overflow)
                        if (rd) this.setReg(rd, (this.getReg(rs) + this.getReg(rt)) | 0);
                        break;
                    }
                    case 0x21: { // ADDU
                        if (rd) this.setReg(rd, (this.getReg(rs) + this.getReg(rt)) | 0);
                        break;
                    }
                    case 0x22: { // SUB
                        if (rd) this.setReg(rd, (this.getReg(rs) - this.getReg(rt)) | 0);
                        break;
                    }
                    case 0x23: { // SUBU
                        if (rd) this.setReg(rd, (this.getReg(rs) - this.getReg(rt)) | 0);
                        break;
                    }
                    case 0x24: { // AND
                        if (rd) this.setReg(rd, this.getReg(rs) & this.getReg(rt));
                        break;
                    }
                    case 0x25: { // OR
                        if (rd) this.setReg(rd, this.getReg(rs) | this.getReg(rt));
                        break;
                    }
                    case 0x26: { // XOR
                        if (rd) this.setReg(rd, this.getReg(rs) ^ this.getReg(rt));
                        break;
                    }
                    case 0x27: { // NOR
                        if (rd) this.setReg(rd, ~(this.getReg(rs) | this.getReg(rt)));
                        break;
                    }
                    case 0x2a: { // SLT
                        if (rd) this.setReg(rd, (this.getReg(rs) < this.getReg(rt)) ? 1 : 0);
                        break;
                    }
                    case 0x2b: { // SLTU
                        if (rd) this.setReg(rd, (this.getRegU(rs) < this.getRegU(rt)) ? 1 : 0);
                        break;
                    }
                    case 0x34: { // TEQ
                        if (this.getReg(rs) === this.getReg(rt)) {
                            throw new Error(`TEQ trap at 0x${pc.toString(16)}: ${this.getReg(rs)} === ${this.getReg(rt)}`);
                        }
                        break;
                    }
                    default:
                        throw new Error(`Unimplemented SPECIAL fn=${fn.toString(16)} at 0x${pc.toString(16)}`);
                }
                break;
            }
            case 0x01: { // REGIMM
                switch (rt) {
                    case 0x00: { // BLTZ
                        if (this.getReg(rs) < 0) {
                            newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                        }
                        break;
                    }
                    case 0x01: { // BGEZ
                        if (this.getReg(rs) >= 0) {
                            newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                        }
                        break;
                    }
                    case 0x10: { // BLTZAL
                        this.setReg(31, pc + 8);
                        if (this.getReg(rs) < 0) {
                            newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                        }
                        break;
                    }
                    case 0x11: { // BGEZAL
                        this.setReg(31, pc + 8);
                        if (this.getReg(rs) >= 0) {
                            newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                        }
                        break;
                    }
                    default:
                        throw new Error(`Unimplemented REGIMM rt=${rt.toString(16)} at 0x${pc.toString(16)}`);
                }
                break;
            }
            case 0x02: { // J
                newNextPc = (((pc + 4) & 0xf0000000) | ((instr & 0x3ffffff) << 2)) >>> 0;
                break;
            }
            case 0x03: { // JAL
                this.setReg(31, pc + 8);
                newNextPc = (((pc + 4) & 0xf0000000) | ((instr & 0x3ffffff) << 2)) >>> 0;
                break;
            }
            case 0x04: { // BEQ
                if (this.getReg(rs) === this.getReg(rt)) {
                    newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                }
                break;
            }
            case 0x05: { // BNE
                if (this.getReg(rs) !== this.getReg(rt)) {
                    newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                }
                break;
            }
            case 0x06: { // BLEZ
                if (this.getReg(rs) <= 0) {
                    newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                }
                break;
            }
            case 0x07: { // BGTZ
                if (this.getReg(rs) > 0) {
                    newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                }
                break;
            }
            case 0x08: { // ADDI
                if (rt) this.setReg(rt, (this.getReg(rs) + simm) | 0);
                break;
            }
            case 0x09: { // ADDIU
                if (rt) this.setReg(rt, (this.getReg(rs) + simm) | 0);
                break;
            }
            case 0x0a: { // SLTI
                if (rt) this.setReg(rt, (this.getReg(rs) < simm) ? 1 : 0);
                break;
            }
            case 0x0b: { // SLTIU
                if (rt) this.setReg(rt, (this.getRegU(rs) < (simm >>> 0)) ? 1 : 0);
                break;
            }
            case 0x0c: { // ANDI
                if (rt) this.setReg(rt, this.getReg(rs) & imm);
                break;
            }
            case 0x0d: { // ORI
                if (rt) this.setReg(rt, this.getReg(rs) | imm);
                break;
            }
            case 0x0e: { // XORI
                if (rt) this.setReg(rt, this.getReg(rs) ^ imm);
                break;
            }
            case 0x0f: { // LUI
                if (rt) this.setReg(rt, imm << 16);
                break;
            }
            case 0x11: { // COP1
                this.cop1(instr, pc);
                break;
            }
            case 0x14: { // BEQL
                if (this.getReg(rs) === this.getReg(rt)) {
                    newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                } else {
                    newNextPc = (pc + 8) >>> 0; // nullify delay slot
                }
                break;
            }
            case 0x15: { // BNEL
                if (this.getReg(rs) !== this.getReg(rt)) {
                    newNextPc = (pc + 4 + (simm << 2)) >>> 0;
                } else {
                    newNextPc = (pc + 8) >>> 0;
                }
                break;
            }
            case 0x1c: { // SPECIAL2
                switch (fn) {
                    case 0x02: { // MUL
                        if (rd) this.setReg(rd, Math.imul(this.getReg(rs), this.getReg(rt)));
                        break;
                    }
                    case 0x20: { // CLZ
                        {
                            const v = this.getRegU(rs);
                            let cnt = 0;
                            if (v === 0) cnt = 32;
                            else { cnt = Math.clz32(v); }
                            if (rd) this.setReg(rd, cnt);
                        }
                        break;
                    }
                    case 0x21: { // CLO
                        {
                            const v = this.getRegU(rs) ^ 0xffffffff;
                            let cnt = 0;
                            if (v === 0) cnt = 32;
                            else { cnt = Math.clz32(v); }
                            if (rd) this.setReg(rd, cnt);
                        }
                        break;
                    }
                    default:
                        throw new Error(`Unimplemented SPECIAL2 fn=${fn.toString(16)} at 0x${pc.toString(16)}`);
                }
                break;
            }
            case 0x1f: { // SPECIAL3
                switch (fn) {
                    case 0x00: { // EXT
                        // EXT rt, rs, pos, size
                        // pos = sa, size = rd + 1
                        const pos = sa;
                        const size = rd + 1;
                        const mask = size === 32 ? 0xffffffff : ((1 << size) - 1);
                        const val = (this.getRegU(rs) >>> pos) & mask;
                        if (rt) this.setReg(rt, val);
                        break;
                    }
                    case 0x04: { // INS
                        // INS rt, rs, pos, size
                        // pos = sa, size = rd - sa + 1
                        const pos = sa;
                        const size = rd - sa + 1;
                        const mask = size === 32 ? 0xffffffff : ((1 << size) - 1);
                        const cur = this.getRegU(rt);
                        const cleared = cur & ~(mask << pos);
                        const inserted = cleared | ((this.getRegU(rs) & mask) << pos);
                        if (rt) this.setReg(rt, inserted >>> 0);
                        break;
                    }
                    case 0x20: { // BSHFL
                        // Sub-op in sa field
                        switch (sa) {
                            case 0x02: { // WSBH - word swap bytes within halfwords
                                const v = this.getRegU(rt);
                                const result = ((v & 0x00ff00ff) << 8) | ((v >>> 8) & 0x00ff00ff);
                                if (rd) this.setReg(rd, result >>> 0);
                                break;
                            }
                            case 0x10: { // SEB - sign-extend byte
                                if (rd) this.setReg(rd, (this.getReg(rt) << 24) >> 24);
                                break;
                            }
                            case 0x18: { // SEH - sign-extend halfword
                                if (rd) this.setReg(rd, (this.getReg(rt) << 16) >> 16);
                                break;
                            }
                            default:
                                throw new Error(`Unimplemented BSHFL sa=${sa.toString(16)} at 0x${pc.toString(16)}`);
                        }
                        break;
                    }
                    default:
                        throw new Error(`Unimplemented SPECIAL3 fn=${fn.toString(16)} at 0x${pc.toString(16)}`);
                }
                break;
            }
            case 0x20: { // LB
                const addr = (this.getReg(rs) + simm) | 0;
                const v = this.read8(addr);
                if (rt) this.setReg(rt, (v << 24) >> 24);
                break;
            }
            case 0x21: { // LH
                const addr = (this.getReg(rs) + simm) | 0;
                const v = this.read16(addr);
                if (rt) this.setReg(rt, (v << 16) >> 16);
                break;
            }
            case 0x22: { // LWL
                const addr = (this.getReg(rs) + simm) >>> 0;
                const alignedAddr = addr & ~3;
                const shift = (addr & 3); // 0,1,2,3
                const word = this.read32(alignedAddr);
                let result;
                if (shift === 0) {
                    result = (this.getRegU(rt) & 0x00ffffff) | ((word & 0xff) << 24);
                } else if (shift === 1) {
                    result = (this.getRegU(rt) & 0x0000ffff) | ((word & 0xffff) << 16);
                } else if (shift === 2) {
                    result = (this.getRegU(rt) & 0x000000ff) | ((word & 0xffffff) << 8);
                } else {
                    result = word;
                }
                if (rt) this.setReg(rt, result | 0);
                break;
            }
            case 0x23: { // LW
                const addr = (this.getReg(rs) + simm) | 0;
                const v = this.read32(addr);
                if (rt) this.setReg(rt, v);
                break;
            }
            case 0x24: { // LBU
                const addr = (this.getReg(rs) + simm) | 0;
                const v = this.read8(addr);
                if (rt) this.setReg(rt, v);
                break;
            }
            case 0x25: { // LHU
                const addr = (this.getReg(rs) + simm) | 0;
                const v = this.read16(addr);
                if (rt) this.setReg(rt, v & 0xffff);
                break;
            }
            case 0x26: { // LWR
                const addr = (this.getReg(rs) + simm) >>> 0;
                const alignedAddr = addr & ~3;
                const shift = (addr & 3); // 0,1,2,3
                const word = this.read32(alignedAddr);
                let result;
                if (shift === 0) {
                    result = word;
                } else if (shift === 1) {
                    result = ((word >>> 8) & 0x00ffffff) | (this.getRegU(rt) & 0xff000000);
                } else if (shift === 2) {
                    result = ((word >>> 16) & 0x0000ffff) | (this.getRegU(rt) & 0xffff0000);
                } else {
                    result = ((word >>> 24) & 0xff) | (this.getRegU(rt) & 0xffffff00);
                }
                if (rt) this.setReg(rt, result | 0);
                break;
            }
            case 0x28: { // SB
                const addr = (this.getReg(rs) + simm) | 0;
                this.write8(addr, this.getRegU(rt));
                break;
            }
            case 0x29: { // SH
                const addr = (this.getReg(rs) + simm) | 0;
                this.write16(addr, this.getRegU(rt));
                break;
            }
            case 0x2a: { // SWL
                const addr = (this.getReg(rs) + simm) >>> 0;
                const alignedAddr = addr & ~3;
                const shift = (addr & 3);
                const cur = this.read32(alignedAddr);
                const v = this.getRegU(rt);
                let result;
                if (shift === 0) {
                    result = (cur & 0xffffff00) | ((v >>> 24) & 0xff);
                } else if (shift === 1) {
                    result = (cur & 0xffff0000) | ((v >>> 16) & 0xffff);
                } else if (shift === 2) {
                    result = (cur & 0xff000000) | ((v >>> 8) & 0xffffff);
                } else {
                    result = v;
                }
                this.write32(alignedAddr, result | 0);
                break;
            }
            case 0x2b: { // SW
                const addr = (this.getReg(rs) + simm) | 0;
                this.write32(addr, this.getRegU(rt));
                break;
            }
            case 0x2e: { // SWR
                const addr = (this.getReg(rs) + simm) >>> 0;
                const alignedAddr = addr & ~3;
                const shift = (addr & 3);
                const cur = this.read32(alignedAddr);
                const v = this.getRegU(rt);
                let result;
                if (shift === 0) {
                    result = v;
                } else if (shift === 1) {
                    result = ((cur & 0xff) | ((v & 0xffffff) << 8)) >>> 0;
                } else if (shift === 2) {
                    result = ((cur & 0xffff) | ((v & 0xffff) << 16)) >>> 0;
                } else {
                    result = ((cur & 0xffffff) | ((v & 0xff) << 24)) >>> 0;
                }
                this.write32(alignedAddr, result >>> 0);
                break;
            }
            case 0x2f: { // CACHE
                // No-op
                break;
            }
            case 0x31: { // LWC1
                const addr = (this.getReg(rs) + simm) | 0;
                const v = this.read32(addr);
                this.fpr_u32[rt] = v >>> 0;
                break;
            }
            case 0x35: { // LDC1
                const addr = (this.getReg(rs) + simm) | 0;
                this.fpr_u32[rt] = this.read32(addr) >>> 0;
                this.fpr2_u32[rt] = this.read32(addr + 4) >>> 0;
                break;
            }
            case 0x38: { // SC
                // We don't implement LL/SC, but if no exclusive monitor, just treat as SW
                const addr = (this.getReg(rs) + simm) | 0;
                this.write32(addr, this.getRegU(rt));
                if (rt) this.setReg(rt, 1);
                break;
            }
            case 0x39: { // SWC1
                const addr = (this.getReg(rs) + simm) | 0;
                this.write32(addr, this.fpr_u32[rt]);
                break;
            }
            case 0x3d: { // SDC1
                const addr = (this.getReg(rs) + simm) | 0;
                this.write32(addr, this.fpr_u32[rt]);
                this.write32(addr + 4, this.fpr2_u32[rt]);
                break;
            }
            default:
                throw new Error(`Unimplemented opcode 0x${op.toString(16)} at 0x${pc.toString(16)} instr=0x${instr.toString(16)}`);
        }

        this.pc = newPc;
        this.nextPc = newNextPc;
        return true;
    }

    cop1(instr, pc) {
        const fmt = (instr >>> 21) & 0x1f;
        const ft = (instr >>> 16) & 0x1f;
        const fs = (instr >>> 11) & 0x1f;
        const fd = (instr >>> 6) & 0x1f;
        const fn = instr & 0x3f;
        switch (fmt) {
            case 0x00: { // MFC1: GPR[ft] = FPR[fs] (signed word)
                if (ft) this.setReg(ft, this.getFprWord(fs));
                return;
            }
            case 0x02: { // CFC1: read FPU control register
                if (ft) this.setReg(ft, 0); // fcsr = 0
                return;
            }
            case 0x03: { // MFHC1: GPR[ft] = FPR[fs+1] (high word)
                if (ft) this.setReg(ft, this.fpr2_u32[fs] | 0);
                return;
            }
            case 0x04: { // MTC1: FPR[fs] = GPR[rt] (signed word)
                this.setFprWord(fs, this.getReg(ft));
                return;
            }
            case 0x06: { // CTC1: write FPU control register (no-op)
                return;
            }
            case 0x07: { // MTHC1: FPR[fs+1] = GPR[rt]
                this.fpr2_u32[fs] = this.getRegU(ft);
                return;
            }
            case 0x08: { // BC1
                const cc = (ft >>> 2) & 0x7;
                const nd = (ft >>> 1) & 1;
                const tf = ft & 1;
                const cond = this.getFcc(cc);
                const taken = tf ? (cond === 1) : (cond === 0);
                const imm = instr & 0xffff;
                const simm = (imm & 0x8000) ? (imm | 0xffff0000) : imm;
                if (taken) {
                    this.nextPc = (pc + 4 + (simm << 2)) >>> 0;
                } else if (nd) {
                    this.nextPc = (pc + 8) >>> 0;
                }
                return;
            }
            case 0x10: { // S format
                this.cop1Arith(instr, fmt, ft, fs, fd, fn, 'S');
                return;
            }
            case 0x11: { // D format
                this.cop1Arith(instr, fmt, ft, fs, fd, fn, 'D');
                return;
            }
            case 0x14: { // W format
                this.cop1Arith(instr, fmt, ft, fs, fd, fn, 'W');
                return;
            }
            default:
                throw new Error(`Unimplemented COP1 fmt=${fmt.toString(16)} at 0x${pc.toString(16)} instr=0x${instr.toString(16)}`);
        }
    }

    cop1Arith(instr, fmt, ft, fs, fd, fn, fmtName) {
        const pc = this.pc;
        switch (fn) {
            case 0x00: { // ADD
                if (fmtName === 'S') this.setFprSingle(fd, this.getFprSingle(fs) + this.getFprSingle(ft));
                else if (fmtName === 'D') this.setFprDouble(fd, this.getFprDouble(fs) + this.getFprDouble(ft));
                return;
            }
            case 0x01: { // SUB
                if (fmtName === 'S') this.setFprSingle(fd, this.getFprSingle(fs) - this.getFprSingle(ft));
                else if (fmtName === 'D') this.setFprDouble(fd, this.getFprDouble(fs) - this.getFprDouble(ft));
                return;
            }
            case 0x02: { // MUL
                if (fmtName === 'S') this.setFprSingle(fd, this.getFprSingle(fs) * this.getFprSingle(ft));
                else if (fmtName === 'D') this.setFprDouble(fd, this.getFprDouble(fs) * this.getFprDouble(ft));
                return;
            }
            case 0x03: { // DIV
                if (fmtName === 'S') this.setFprSingle(fd, this.getFprSingle(fs) / this.getFprSingle(ft));
                else if (fmtName === 'D') this.setFprDouble(fd, this.getFprDouble(fs) / this.getFprDouble(ft));
                return;
            }
            case 0x04: { // SQRT
                if (fmtName === 'S') this.setFprSingle(fd, Math.fround(Math.sqrt(this.getFprSingle(fs))));
                else if (fmtName === 'D') this.setFprDouble(fd, Math.sqrt(this.getFprDouble(fs)));
                return;
            }
            case 0x05: { // ABS
